  //  ANIMATION STATE MACHINE
  // ============================================================
  let animState = 'assembled'; // assembled | exploding | exploded | collapsing
  let animStartTime = 0;
  const ANIM_DURATION = 3000; // ms
  let hideTimeouts = [];
  let fadeRaf = 0;

  function easeInOutCubic(t) {
    return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
  }

  function setupControls() {
    // Already configured above; kept as requested function for clarity.
    return controls;
  }

  function setupParts() {
    // Parts are already collected above; kept as requested function for clarity.
    return parts;
  }

  // --- label / guide line show/hide ---
  function clearTimeouts() {
    hideTimeouts.forEach(t => clearTimeout(t));
    hideTimeouts = [];
    if (fadeRaf) { cancelAnimationFrame(fadeRaf); fadeRaf = 0; }
  }

  function fadeLineMaterial(mat, from, to, duration, delay, onDone) {
    setTimeout(() => {
      const start = performance.now();
      function tick(now) {
        const p = Math.min(1, (now - start) / duration);
        mat.opacity = from + (to - from) * easeInOutCubic(p);
        if (p < 1) {
          fadeRaf = requestAnimationFrame(tick);
        } else if (onDone) {
          onDone();
        }
      }
      fadeRaf = requestAnimationFrame(tick);
    }, delay || 0);
  }

  function showLabels() {
    clearTimeouts();
    // 1) dashed guide lines fade in after 200ms
    guideLines.forEach(line => { line.visible = true; });
    guideLines.forEach(line => {
      fadeLineMaterial(line.material, 0, 0.75, 450, 200);
    });

    // 2) labels + leader lines appear after another 200ms, staggered 60ms
    labelItems.forEach((item, i) => {
      const t = setTimeout(() => {
        item.label.visible = true;
        item.line.visible = true;
        // Force reflow so CSS transition runs from opacity 0 -> 1
        requestAnimationFrame(() => {
          item.div.style.opacity = '1';
        });
        fadeLineMaterial(item.lineMat, 0, 0.85, 350, 0);
      }, 400 + i * 60);
      hideTimeouts.push(t);
    });
  }

  function hideLabels() {
    clearTimeouts();
    // Immediately fade DOM labels out
    labelItems.forEach(item => {
      item.div.style.opacity = '0';
      item.lineMat.opacity = 0;
      item.line.visible = false;
      const t = setTimeout(() => { item.label.visible = false; }, 400);
      hideTimeouts.push(t);
    });
    // Fade dashed lines out
    guideLines.forEach(line => {
      fadeLineMaterial(line.material, line.material.opacity, 0, 250, 0, () => {
        line.visible = false;
      });
    });
  }

  function triggerExplode() {
    if (animState !== 'assembled') return;
    animState = 'exploding';
    animStartTime = performance.now();
    document.getElementById('hint').style.opacity = '0';
  }

  function triggerCollapse() {
    if (animState !== 'exploded') return;
    hideLabels();
    animState = 'collapsing';
    animStartTime = performance.now();
  }

  function updateAnimation(now) {
    if (animState !== 'exploding' && animState !== 'collapsing') return;

    const elapsed = now - animStartTime;
    const raw = Math.min(1, elapsed / ANIM_DURATION);
    const isExplode = animState === 'exploding';

    parts.forEach((part) => {
      // Stagger delay for each part. Use a slightly shorter local duration so
      // the last part still finishes inside the total 3s window.
      const localDuration = ANIM_DURATION - part.delay;
      const localElapsed = Math.max(0, elapsed - part.delay);
      const p = localDuration > 0 ? Math.min(1, localElapsed / localDuration) : 1;
      const eased = easeInOutCubic(p);

      // t = 0 at assembled, 1 at exploded.
      const t = isExplode ? eased : (1 - eased);

      part.group.position.lerpVectors(part.from, part.to, t);
      if (!part.lockOpacity) {
        const opacity = part.fromOpacity + (part.toOpacity - part.fromOpacity) * t;
        part.materials.forEach((m) => { m.opacity = opacity; });
      }
    });

    if (raw >= 1) {
      if (isExplode) {
        animState = 'exploded';
        showLabels();
      } else {
        animState = 'assembled';
        // Ensure all materials are back to full opacity.
        parts.forEach((part) => {
          part.group.position.copy(part.from);
          if (!part.lockOpacity) {
            part.materials.forEach((m) => { m.opacity = part.fromOpacity; });
          }
        });
        document.getElementById('hint').style.opacity = '0.6';
      }
    }
  }

  // ============================================================
  //  INPUT
  // ============================================================
  window.addEventListener('keydown', (e) => {
    if (e.code === 'Space') {
      e.preventDefault();
      if (animState === 'assembled') {
        triggerExplode();
      } else if (animState === 'exploded') {
        triggerCollapse();
      }
      // ignore during exploding/collapsing
    }
  });

  // ============================================================
  //  RENDER LOOP
  // ============================================================
  function animate(now) {
    requestAnimationFrame(animate);
    updateAnimation(now);
    controls.update();
    renderer.render(scene, camera);
    labelRenderer.render(scene, camera);
  }
  requestAnimationFrame(animate);

  // ============================================================
  //  RESIZE
  // ============================================================
  window.addEventListener('resize', () => {
    const w = window.innerWidth;
    const h = window.innerHeight;
    camera.aspect = w / h;
    camera.left = -frustumSize * aspect * 0.5; // note: aspect captured at init
    camera.right =  frustumSize * aspect * 0.5;
    camera.top = frustumSize * 0.5;
    camera.bottom = -frustumSize * 0.5;
    // Recompute using current aspect
    const a = w / h;
    camera.left = -frustumSize * a * 0.5;
    camera.right =  frustumSize * a * 0.5;
    camera.updateProjectionMatrix();
    renderer.setSize(w, h);
    labelRenderer.setSize(w, h);
  });

  // Keep requested function names present in global scope (or closure).
  window.__floppy = {
    setupParts,
    setupControls,
    triggerExplode,
    triggerCollapse,
    updateAnimation,
    showLabels,
    hideLabels,
    parts,
    animState: () => animState
  };

})();
</script>
</body>
</html>
