// ============================================================
//  DUST LINER (C-shape ring with a head window notch)
// ============================================================
function createDustLiner() {
  const group = new THREE.Group();
  const shape = new THREE.Shape();
  // Outer circle radius 24 (slightly larger than disk 22)
  shape.absarc(0, 0, 24, 0, Math.PI * 2, false);
  // Inner circle
  shape.holes.push(circleHolePath(0, 0, 12));
  // Rectangular head-window cut from the ring (open to the front edge)
  // Use a hole that reaches the outer boundary as a C-shaped notch.
  const notch = new THREE.Path();
  const nw = HEAD_WINDOW.width + 4; // 10
  const nd = HEAD_WINDOW.depth + 6; // 20
  const nx = HEAD_WINDOW.cx;
  const nz = 24; // start at outer edge
  // In shape space y = -z; make a rectangular notch from outer edge inward.
  notch.moveTo(nx - nw * 0.5, -nz);
  notch.lineTo(nx + nw * 0.5, -nz);
  notch.lineTo(nx + nw * 0.5, -(nz - nd));
  notch.lineTo(nx - nw * 0.5, -(nz - nd));
  notch.closePath();
  shape.holes.push(notch);

  const geo = new THREE.ExtrudeGeometry(shape, {
    depth: 0.15,
    bevelEnabled: false
  });
  geo.rotateX(-Math.PI * 0.5);
  geo.translate(0, -0.075, 0);

