    // slot at the front-left. The slot sides are parallel to the Z axis.
    const R = 24; // outer radius
    const r = 12; // inner radius
    const xL = -12; // left side of the slot (on inner circle)
    const xR = -4;  // right side of the slot
    const yOuterL = -Math.sqrt(R * R - xL * xL);
    const yOuterR = -Math.sqrt(R * R - xR * xR);
    const yInnerL = -Math.sqrt(r * r - xL * xL);
    const yInnerR = -Math.sqrt(r * r - xR * xR);

